// Accept either { imageUrl } or { imageBase64 } (data URL) in the webhook body
const raw = $('Webhook').first().json.body || $('Webhook').first().json || {};
let imageRef = raw.imageUrl || raw.image_url || raw.image || null;
if (!imageRef && raw.imageBase64) {
  // Allow raw base64 without the data: prefix - wrap it
  imageRef = raw.imageBase64.startsWith('data:') ? raw.imageBase64 : 'data:image/jpeg;base64,' + raw.imageBase64;
}
if (!imageRef) {
  throw new Error('No image provided. Send JSON with "imageUrl" (public URL) or "imageBase64" (data URL).');
}
return [{ json: { imageRef } }];

// Build the OpenAI vision request body. Prompt: stock metadata (title, description, 20-40 keywords).
const imageRef = $json.imageRef;
const body = {
  model: 'gpt-4o-mini',
  messages: [
    {
      role: 'system',
      content: 'You are a professional stock-photo metadata writer. You write metadata that makes images SELL on stock marketplaces (Adobe Stock, Shutterstock, Getty).'
    },
    {
      role: 'user',
      content: [
        {
          type: 'text',
          text: 'Analyze this image and return ONLY raw JSON (no markdown, no code fences) with exactly these fields: {"title": "compelling stock title under 12 words", "description": "2-3 sentence description with subject, setting, mood, use cases", "keywords": ["20-40 lowercase keywords", "comma-separated array"]}. Keywords: mix of subject, style, concept, mood, and usage keywords a buyer would search.'
        },
        { type: 'image_url', image_url: { url: imageRef } }
      ]
    }
  ],
  temperature: 0.3,
  max_tokens: 800
};
return [{ json: { requestBody: JSON.stringify(body) } }];

// Parse the LLM response; tolerate code fences and whitespace
let content = $json.choices && $json.choices[0] && $json.choices[0].message
  ? $json.choices[0].message.content : String($json.content || '');
content = content.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
let meta;
try {
  meta = JSON.parse(content);
} catch (e) {
  // Fallback: extract first {...} block
  const m = content.match(/\{[\s\S]*\}/);
  meta = m ? JSON.parse(m[0]) : {};
}
const title = (meta.title || 'Untitled').trim();
const description = (meta.description || '').trim();
const keywords = Array.isArray(meta.keywords) ? meta.keywords.map(k => String(k).trim()).filter(Boolean) : [];
if (!title || !description || keywords.length === 0) {
  throw new Error('Bad LLM output: missing title/description/keywords. Got: ' + content.slice(0, 200));
}
return [{ json: { title, description, keywords, keyword_count: keywords.length } }];

// Emit the metadata row as CSV (RFC-4180-ish quoting) + a JSON view for the response
const t = $json.title.replace(/"/g, '""');
const d = $json.description.replace(/"/g, '""');
const kw = $json.keywords.join('; ').replace(/"/g, '""');
const csvLine = `"${t}","${d}","${kw}"`;
const csvHeader = '"title","description","keywords"';
return [{
  json: {
    title: $json.title,
    description: $json.description,
    keywords: $json.keywords,
    keyword_count: $json.keyword_count,
    csv_row: csvLine,
    csv: csvHeader + '\n' + csvLine
  }
}];
